#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1          // у нас нет отдельного пина сброса
#define OLED_ADDR     0x3C        // адрес I2C (иногда 0x3D)

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

unsigned int counter = 0;

void setup() {
    Serial.begin(9600);
    Wire.begin();                 // Arduino — мастер шины I2C

    if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
        Serial.println("SSD1306 not found!");
        for (;;);                 // если экран не найден — стоп
    }

    display.clearDisplay();
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);

    display.setCursor(0, 0);
    display.println("I2C OLED ready!");
    display.display();
    delay(1500);
}

void loop() {
    display.clearDisplay();

    // Заголовок
    display.setTextSize(1);
    display.setCursor(0, 0);
    display.println("I2C SSD1306 demo");

    // Крупный счётчик
    display.setTextSize(3);
    display.setCursor(0, 24);
    display.print("Cnt:");
    display.print(counter);

    display.display();

    Serial.print("Counter = ");
    Serial.println(counter);

    counter++;
    if (counter > 9999) counter = 0;

    delay(1000);
}
